package index

import (
	"encoding/json"
	"math"
	"os"
	"path/filepath"
	"slices"
	"testing"
)

// The sixth parity surface: FAISS IndexFlatIP, as the sidecar would compute an
// EXACT top-k, against this package's in-process scan. Generated by
// scripts/writeups/dump_parity_fixtures.py:search_cases. Regenerate
// deliberately (`make fixtures`).
//
// Scope, stated as narrowly as the fixture's docstring states it: rung 1 is
// HNSW, which is approximate, so rung 2 is not expected to reproduce rung 1's
// slate. What this proves is that the Go scan computes the same EXACT answer
// FAISS does -- scores, order and the +1 item shift -- so the rung 1 to rung 2
// difference is exactly the approximate-vs-exact gap already measured, and not
// an unknown on top of it.
const searchFixture = "../../../testdata/search_cases.json"

// scoreTolerance absorbs float32 accumulation order: FAISS sums the dot product
// with SIMD lanes, this scan sums left to right. Over 8 unit-norm dimensions
// the difference is a few ULPs; 1e-5 is orders above that and orders below
// any gap between two genuinely different rows in the fixture.
const scoreTolerance = 1e-5

type searchCase struct {
	Name           string      `json:"name"`
	K              int         `json:"k"`
	Dim            int         `json:"dim"`
	Vectors        [][]float32 `json:"vectors"`
	Queries        [][]float32 `json:"queries"`
	ExpectedItems  [][]int32   `json:"expected_items"`
	ExpectedScores [][]float32 `json:"expected_scores"`
}

func loadSearchCases(t *testing.T) []searchCase {
	t.Helper()
	raw, err := os.ReadFile(filepath.Clean(searchFixture))
	if err != nil {
		t.Fatalf("reading fixture: %v (run `make fixtures`)", err)
	}
	var cases []searchCase
	if err := json.Unmarshal(raw, &cases); err != nil {
		t.Fatalf("parsing fixture: %v", err)
	}
	if len(cases) == 0 {
		t.Fatal("fixture is empty; a parity test over no cases passes and proves nothing")
	}
	return cases
}

// TestExactSearchMatchesFAISS compares tied groups as SETS. FAISS has no single
// tie order -- on two identical rows it keeps the earlier at k=1 and the later
// at k>=5, because its k=1 path and heap path are different code -- so chasing
// its order would pin this test to an implementation detail FAISS itself does
// not hold constant. Within a group, the scores still have to match.
func TestExactSearchMatchesFAISS(t *testing.T) {
	for _, tc := range loadSearchCases(t) {
		t.Run(tc.Name, func(t *testing.T) {
			flat, err := Load(write(t, tc.Vectors, standardMeta(len(tc.Vectors), tc.Dim)))
			if err != nil {
				t.Fatalf("Load: %v", err)
			}

			for q, query := range tc.Queries {
				items, scores, err := flat.Search(query, tc.K)
				if err != nil {
					t.Fatalf("query %d: %v", q, err)
				}

				// FAISS pads past the table with -1, which the fixture maps to
				// item 0; the scan clamps k instead. Compare the real results.
				var wantItems []int32
				var wantScores []float32
				for i, item := range tc.ExpectedItems[q] {
					if item > 0 {
						wantItems = append(wantItems, item)
						wantScores = append(wantScores, tc.ExpectedScores[q][i])
					}
				}
				if len(items) != len(wantItems) {
					t.Fatalf("query %d: %d results, FAISS returned %d", q, len(items), len(wantItems))
				}

				for i := range wantScores {
					if math.Abs(float64(scores[i]-wantScores[i])) > scoreTolerance {
						t.Fatalf("query %d slot %d: score %v, FAISS %v", q, i, scores[i], wantScores[i])
					}
				}

				for start := 0; start < len(wantItems); {
					end := start + 1
					for end < len(wantItems) &&
						math.Abs(float64(wantScores[end]-wantScores[start])) <= scoreTolerance {
						end++
					}
					// A group cut by k can hold different members of the same
					// tie on each side; the score check above already covers it.
					if end == len(wantItems) && len(wantItems) == tc.K && end-start > 1 {
						break
					}
					got := slices.Clone(items[start:end])
					want := slices.Clone(wantItems[start:end])
					slices.Sort(got)
					slices.Sort(want)
					if !slices.Equal(got, want) {
						t.Fatalf("query %d slots %d-%d: items %v, FAISS %v", q, start, end-1, got, want)
					}
					start = end
				}
			}
		})
	}
}

// TestTheFixtureExercisesTheHardCases guards the fixture itself: a parity test
// whose negative-score or tie cases were silently regenerated away would keep
// passing while proving less.
func TestTheFixtureExercisesTheHardCases(t *testing.T) {
	var sawNegativeBest, sawTie, sawPadding bool
	for _, tc := range loadSearchCases(t) {
		for q := range tc.Queries {
			scores := tc.ExpectedScores[q]
			if len(scores) > 0 && scores[0] < 0 {
				sawNegativeBest = true
			}
			for i := 1; i < len(scores); i++ {
				if tc.ExpectedItems[q][i] > 0 && scores[i] == scores[i-1] {
					sawTie = true
				}
			}
			if slices.Contains(tc.ExpectedItems[q], 0) {
				sawPadding = true
			}
		}
	}
	if !sawNegativeBest || !sawTie || !sawPadding {
		t.Errorf("fixture lost a case: negative best %v, exact tie %v, k past the table %v",
			sawNegativeBest, sawTie, sawPadding)
	}
}
